document.getElementById('appointmentForm').addEventListener('submit', event => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const locale = translations[currentLanguage];
    const fullName = `${form.get('firstName')} ${form.get('lastName')}`.trim();
    const subject = `${locale.mailSubject} ${fullName}`;
    const body = [
        `${locale.mailName}: ${fullName}`,
        `${locale.mailPhone}: ${form.get('phone')}`,
        `${locale.mailEmail}: ${form.get('email')}`,
        `${locale.mailMessage}: ${form.get('message') || '-'}`
    ].join('\n');
    document.getElementById('formStatus').textContent = locale.formStatusPreparing;
    window.location.href = `mailto:info@kassen-keskin.de?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
});

