function showLegal(id, e) {
    if (e) e.preventDefault();
    document.getElementById('top').style.display = 'none';
    ['agb', 'datenschutz', 'impressum'].forEach(sec => {
        const el = document.getElementById(sec);
        if (el) el.style.display = 'none';
    });
    const target = document.getElementById(id);
    if (target) {
        target.style.display = 'block';
        document.body.style.overflow = 'auto';
        window.scrollTo(0, 0);
    }
}

function hideLegal() {
    document.getElementById('top').style.display = '';
    ['agb', 'datenschutz', 'impressum'].forEach(sec => {
        const el = document.getElementById(sec);
        if (el) el.style.display = 'none';
    });
    window.scrollTo(0, 0);
}

// Simple elegant fade-in animations and Lightbox logic
document.querySelectorAll('.fade-in, .fade-in-delayed').forEach(el => {
    // Add small delay for visual effect
    setTimeout(() => {
        el.style.opacity = '1';
        el.style.transform = 'translateY(0)';
    }, 100);
});

// Lightbox / Zoom Logic
const modal = document.getElementById("imageModal");
const modalImg = document.getElementById("modalImg");
const images = Array.from(document.querySelectorAll('.gallery-item img'));
let currentIndex = 0;

if (modal && modalImg && images.length > 0) {
    images.forEach((img, index) => {
        img.style.cursor = 'zoom-in';
        img.onclick = function(){
            modal.style.display = "flex";
            modal.style.alignItems = "center";
            modal.style.justifyContent = "center";
            modalImg.src = this.src;
            modalImg.classList.remove("zoomed"); // Reset zoom state when opened
            currentIndex = index;
        }
    });

    // Navigation Arrows
    document.querySelector(".prev-modal").onclick = function(e) {
        e.stopPropagation();
        currentIndex = (currentIndex > 0) ? currentIndex - 1 : images.length - 1;
        modalImg.src = images[currentIndex].src;
        modalImg.classList.remove("zoomed");
    };

    document.querySelector(".next-modal").onclick = function(e) {
        e.stopPropagation();
        currentIndex = (currentIndex < images.length - 1) ? currentIndex + 1 : 0;
        modalImg.src = images[currentIndex].src;
        modalImg.classList.remove("zoomed");
    };

    // Toggle Zoom inside Lightbox
    modalImg.onclick = function(e) {
        e.stopPropagation(); // don't trigger the modal close background click
        this.classList.toggle("zoomed");
    }

    // Close logic
    document.querySelector(".close-modal").onclick = function() {
        modal.style.display = "none";
    }
    modal.onclick = function() {
        modal.style.display = "none";
    }
}
